//! Real CLI smoke: an agent-like sequence must produce a usable DXF and PNG.
//! These are generated by cadcraft-cli itself, never illustrative mockups.

use std::process::Command;

#[test]
fn agent_commands_create_dxf_and_render_real_png() {
    let root=std::env::temp_dir().join(format!("cad360-agent-render-{}",std::process::id()));
    std::fs::create_dir_all(&root).expect("create smoke folder");
    let dxf=root.join("agent_plate.dxf");
    let png=root.join("agent_plate.png");
    let output=Command::new(env!("CARGO_BIN_EXE_cadcraft-cli"))
        .args(["run","--metric",
            "--cmd",r#"line {"points":[[0,0],[100,0]]}"#,
            "--cmd",r#"line {"points":[[100,0],[100,60]]}"#,
            "--cmd",r#"line {"points":[[100,60],[0,60]]}"#,
            "--cmd",r#"line {"points":[[0,60],[0,0]]}"#,
            "--cmd",r#"circle {"center":[10,10],"radius":4}"#,
            "--cmd",r#"circle {"center":[90,50],"radius":4}"#,
            "--save",dxf.to_str().expect("DXF path"),
            "--export",png.to_str().expect("PNG path"),"--view","extents"])
        .output().expect("run CAD CLI");
    assert!(output.status.success(),"CLI failed: {}",String::from_utf8_lossy(&output.stderr));
    let picture=std::fs::read(&png).expect("real rendered PNG must exist");
    assert!(picture.starts_with(b"\x89PNG\r\n\x1a\n"),"render must be valid PNG");
    assert!(picture.len()>2048,"render unexpectedly small: {} bytes",picture.len());
    let drawing=std::fs::read(&dxf).expect("DXF output must exist");
    assert!(drawing.len()>1024,"DXF unexpectedly small");
    let inspect=Command::new(env!("CARGO_BIN_EXE_cadcraft-cli"))
        .args(["info",dxf.to_str().expect("DXF path")])
        .output().expect("reopen saved DXF");
    assert!(inspect.status.success(),"reopening DXF failed: {}",String::from_utf8_lossy(&inspect.stderr));
    let summary=String::from_utf8_lossy(&inspect.stdout);
    assert!(summary.contains("Circle"),"reloaded DXF lost circles: {summary}");
    assert!(summary.contains("Line"),"reloaded DXF lost lines: {summary}");
    let _=std::fs::remove_dir_all(&root);
}
